import{_ as e,c as i,o as n,a0 as r}from"./chunks/framework.DKRgXLPU.js";const t=JSON.parse('{"title":"Building Pre-Shot Routines","description":"Develop a consistent pre-shot routine that anchors your focus, manages pressure, and creates the conditions for peak performance in pétanque.","frontmatter":{"title":"Building Pre-Shot Routines","description":"Develop a consistent pre-shot routine that anchors your focus, manages pressure, and creates the conditions for peak performance in pétanque."},"headers":[],"relativePath":"de/blog/pre-shot-routines.md","filePath":"de/blog/pre-shot-routines.md"}');const a=e({name:"de/blog/pre-shot-routines.md"},[["render",function(e,t,a,s,u,l){return n(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="aufbau-von-pre-wurf-routinen" tabindex="-1">Aufbau von Pre-Wurf-Routinen <a class="header-anchor" href="#aufbau-von-pre-wurf-routinen" aria-label="Permalink to &quot;Aufbau von Pre-Wurf-Routinen&quot;">​</a></h1><p>Der Unterschied zwischen einem guten und einem großartigen Wurf zeigt sich oft schon, bevor die Kugel die Hand verlässt. Eine gut durchdachte Vorbereitungsroutine ist Ihr Anker im Wettkampfgetümmel – eine verlässliche Abfolge, die Körper und Geist optimal auf den Wurf vorbereitet.</p><h2 id="warum-vorbereitungsrituale-vor-dem-spritzen-wichtig-sind" tabindex="-1">Warum Vorbereitungsrituale vor dem Spritzen wichtig sind <a class="header-anchor" href="#warum-vorbereitungsrituale-vor-dem-spritzen-wichtig-sind" aria-label="Permalink to &quot;Warum Vorbereitungsrituale vor dem Spritzen wichtig sind&quot;">​</a></h2><p>Spitzensportler aller Sportarten nutzen Vorbereitungsrituale. Beim Boule, wo jeder Wurf einzeln erfolgt und sich zwischen den Würfen Druck aufbauen kann, erfüllen diese Rituale mehrere Zwecke:</p><ul><li><strong>Konstanz</strong>: Gleiche Vorbereitung führt zu konstanterer Ausführung</li><li><strong>Fokus</strong>: Gibt Ihrem Geist eine konstruktive Aufgabe, anstatt ihn zu grübeln.</li><li><strong>Übergang</strong>: Hilft Ihnen beim Wechsel vom Denken zum Handeln.</li><li><strong>Stressmanagement</strong>: Vertraute Handlungen beruhigen das Nervensystem.</li><li><strong>Zurücksetzen</strong>: Löscht die vorherige Aufnahme aus Ihrem Gedächtnis</li></ul><h2 id="anatomie-einer-effektiven-routine" tabindex="-1">Anatomie einer effektiven Routine <a class="header-anchor" href="#anatomie-einer-effektiven-routine" aria-label="Permalink to &quot;Anatomie einer effektiven Routine&quot;">​</a></h2><p>Eine gute Vorbereitungsroutine vor dem Wurf besteht aus drei Phasen:</p><h3 id="phase-1-beurteilung-5-10-sekunden" tabindex="-1">Phase 1: Beurteilung (5-10 Sekunden) <a class="header-anchor" href="#phase-1-beurteilung-5-10-sekunden" aria-label="Permalink to &quot;Phase 1: Beurteilung (5-10 Sekunden)&quot;">​</a></h3><ul><li>Lies das Gelände</li><li>Visualisieren Sie das beabsichtigte Ergebnis</li><li>Wählen Sie Ihren Wurftyp</li><li>Stehe zu deiner Entscheidung.</li></ul><h3 id="phase-2-vorbereitung-5-10-sekunden" tabindex="-1">Phase 2: Vorbereitung (5-10 Sekunden) <a class="header-anchor" href="#phase-2-vorbereitung-5-10-sekunden" aria-label="Permalink to &quot;Phase 2: Vorbereitung (5-10 Sekunden)&quot;">​</a></h3><ul><li>Nehmen Sie Ihre Position ein</li><li>Finde deinen Halt</li><li>Beruhige deine Atmung</li><li>Spüre das Gewicht des Balles</li></ul><h3 id="phase-3-ausfuhrung-3-5-sekunden" tabindex="-1">Phase 3: Ausführung (3-5 Sekunden) <a class="header-anchor" href="#phase-3-ausfuhrung-3-5-sekunden" aria-label="Permalink to &quot;Phase 3: Ausführung (3-5 Sekunden)&quot;">​</a></h3><ul><li>Letzten Fokus auf das Ziel</li><li>Vertraue deinem Körper</li><li>Unüberlegtes Loslassen</li><li>Setzen Sie es natürlich fort</li></ul><h2 id="aufbau-ihrer-personlichen-routine" tabindex="-1">Aufbau Ihrer persönlichen Routine <a class="header-anchor" href="#aufbau-ihrer-personlichen-routine" aria-label="Permalink to &quot;Aufbau Ihrer persönlichen Routine&quot;">​</a></h2><h3 id="schritt-1-beobachten-sie-ihre-aktuellen-verhaltensmuster" tabindex="-1">Schritt 1: Beobachten Sie Ihre aktuellen Verhaltensmuster <a class="header-anchor" href="#schritt-1-beobachten-sie-ihre-aktuellen-verhaltensmuster" aria-label="Permalink to &quot;Schritt 1: Beobachten Sie Ihre aktuellen Verhaltensmuster&quot;">​</a></h3><p>Bevor Sie eine neue Routine entwickeln, achten Sie darauf, was Sie bereits tun:</p><ul><li>Was tun Sie vor erfolgreichen Würfen?</li><li>Was ändert sich, wenn man unter Druck steht?</li><li>Was fühlt sich für dich natürlich an?</li></ul><h3 id="schritt-2-entwerfen-sie-ihre-sequenz" tabindex="-1">Schritt 2: Entwerfen Sie Ihre Sequenz <a class="header-anchor" href="#schritt-2-entwerfen-sie-ihre-sequenz" aria-label="Permalink to &quot;Schritt 2: Entwerfen Sie Ihre Sequenz&quot;">​</a></h3><p>Erstellen Sie eine Routine, die Folgendes beinhaltet:</p><p><strong>Physikalische Elemente:</strong></p><ul><li>Wie Sie sich dem Kreis nähern</li><li>Wie man die Boule aufnimmt und hält</li><li>Ihre Haltung und Positionierung</li><li>Ein bestimmtes Atemmuster</li></ul><p><strong>Mentale Elemente:</strong></p><ul><li>Eine Visualisierung des Ergebnisses</li><li>Ein Fokuswort oder eine Fokusphrase</li><li>Ein Entscheidungspunkt (der Moment, in dem man sich entscheidet: &quot;Das ist der Wurf&quot;)</li></ul><h3 id="schritt-3-halte-es-einfach" tabindex="-1">Schritt 3: Halte es einfach <a class="header-anchor" href="#schritt-3-halte-es-einfach" aria-label="Permalink to &quot;Schritt 3: Halte es einfach&quot;">​</a></h3><p>Ihre Routine sollte wie folgt aussehen:</p><ul><li><strong>Kurz genug</strong>, um auch unter Druck durchzuhalten (insgesamt 15-25 Sekunden).</li><li><strong>Einfach genug, um sich das auch in Stresssituationen zu merken</strong></li><li><strong>Flexibel genug</strong>, um sich an unterschiedliche Situationen anzupassen</li></ul><h2 id="beispielroutinen" tabindex="-1">Beispielroutinen <a class="header-anchor" href="#beispielroutinen" aria-label="Permalink to &quot;Beispielroutinen&quot;">​</a></h2><h3 id="die-routine-des-pointers" tabindex="-1">Die Routine des Pointers <a class="header-anchor" href="#die-routine-des-pointers" aria-label="Permalink to &quot;Die Routine des Pointers&quot;">​</a></h3><ol><li>Hinter dem Kreis stehen, das Gelände einschätzen</li><li>Visualisiere die Bahn und den Landepunkt der Boule-Kugel.</li><li>Tritt in den Kreis, finde deine Haltung</li><li>Drei langsame Atemzüge, während man die Kugel spürt.</li><li>Blick aufs Ziel, loslassen!</li></ol><h3 id="die-routine-des-schutzen" tabindex="-1">Die Routine des Schützen <a class="header-anchor" href="#die-routine-des-schutzen" aria-label="Permalink to &quot;Die Routine des Schützen&quot;">​</a></h3><ol><li>Identifizieren Sie die Zielboule, wählen Sie den Winkel</li><li>Visualisieren Sie die Auswirkungen und das Ergebnis.</li><li>Betrete den Kreis mit einer klaren Absicht.</li><li>Ein tiefer Atemzug, spüre das Gewicht</li><li>Blick auf das Ziel richten, ausführen</li></ol><h2 id="haufige-fehler-die-es-zu-vermeiden-gilt" tabindex="-1">Häufige Fehler, die es zu vermeiden gilt <a class="header-anchor" href="#haufige-fehler-die-es-zu-vermeiden-gilt" aria-label="Permalink to &quot;Häufige Fehler, die es zu vermeiden gilt&quot;">​</a></h2><h3 id="zu-lang" tabindex="-1">Zu lang <a class="header-anchor" href="#zu-lang" aria-label="Permalink to &quot;Zu lang&quot;">​</a></h3><p>Dauert Ihre Routine länger als 30 Sekunden, denken Sie zu viel nach. Lange Routinen geben der Angst mehr Zeit, sich aufzubauen.</p><h3 id="zu-starr" tabindex="-1">Zu starr <a class="header-anchor" href="#zu-starr" aria-label="Permalink to &quot;Zu starr&quot;">​</a></h3><p>Wenn Ihre Routine durch irgendeine Unterbrechung gestört wird, ist sie zu fragil. Bauen Sie Flexibilität ein – falls etwas Ihre Konzentration unterbricht, schaffen Sie einen Auslöser für einen Neustart.</p><h3 id="seilspringen-unter-druck" tabindex="-1">Seilspringen unter Druck <a class="header-anchor" href="#seilspringen-unter-druck" aria-label="Permalink to &quot;Seilspringen unter Druck&quot;">​</a></h3><p>Die Routine ist besonders wichtig, wenn der Druck am größten ist. Wenn man sie in Stresssituationen aufgibt, verliert man ihre schützende Wirkung.</p><h3 id="schwerpunkt-mechanik" tabindex="-1">Schwerpunkt Mechanik <a class="header-anchor" href="#schwerpunkt-mechanik" aria-label="Permalink to &quot;Schwerpunkt Mechanik&quot;">​</a></h3><p>Dein Training sollte mit dem Fokus auf dem Ergebnis enden, nicht auf der Technik. „Triff das Ziel“, nicht „Halte den Ellbogen gestreckt“.</p><h2 id="uben-sie-ihre-routine" tabindex="-1">Üben Sie Ihre Routine <a class="header-anchor" href="#uben-sie-ihre-routine" aria-label="Permalink to &quot;Üben Sie Ihre Routine&quot;">​</a></h2><h3 id="in-ausbildung" tabindex="-1">In Ausbildung <a class="header-anchor" href="#in-ausbildung" aria-label="Permalink to &quot;In Ausbildung&quot;">​</a></h3><ul><li>Nutze deine komplette Wurftechnik für jeden Wurf, selbst für lockere Würfe.</li><li>Die Zeitmessung dient der Sicherstellung der Konsistenz.</li><li>Üben Sie mit Ablenkungen, um Ihre Widerstandsfähigkeit zu stärken.</li></ul><h3 id="gebaudeautomatisierung" tabindex="-1">Gebäudeautomatisierung <a class="header-anchor" href="#gebaudeautomatisierung" aria-label="Permalink to &quot;Gebäudeautomatisierung&quot;">​</a></h3><p>Ziel ist es, dass Ihre Routine zur Gewohnheit wird – etwas, das Sie tun, ohne darüber nachzudenken. Das erfordert Wiederholung:</p><ul><li>Mehr als 100 Würfe mit der gleichen Routine</li><li>Konsequente Anwendung in verschiedenen Situationen</li><li>Allmähliche Steigerung des Drucks bei gleichzeitiger Beibehaltung der Routine</li></ul><h2 id="anpassung-an-den-wettbewerb" tabindex="-1">Anpassung an den Wettbewerb <a class="header-anchor" href="#anpassung-an-den-wettbewerb" aria-label="Permalink to &quot;Anpassung an den Wettbewerb&quot;">​</a></h2><p>Bei Wettkämpfen müssen Sie Ihre Routine möglicherweise leicht anpassen:</p><ul><li><strong>Zeitdruck</strong>: Halten Sie eine Kurzfassung bereit.</li><li><strong>Wetterbedingungen</strong>: Passen Sie die physikalischen Elemente nach Bedarf an.</li><li><strong>Situationen mit hohem Druck</strong>: Etwas langsamer fahren, nicht beschleunigen.</li></ul><h2 id="die-reset-routine" tabindex="-1">Die Reset-Routine <a class="header-anchor" href="#die-reset-routine" aria-label="Permalink to &quot;Die Reset-Routine&quot;">​</a></h2><p>Genauso wichtig ist, was Sie nach einem Wurf tun:</p><ol><li><strong>Akzeptiere das Ergebnis</strong> – ob gut oder schlecht, es ist geschehen.</li><li><strong>Körperliche Auszeit</strong> – einen Schritt zurücktreten, Anspannung lösen.</li><li><strong>Mentale Neuorientierung</strong> – den Wurf aus deinem Kopf verbannen</li><li><strong>Bereite dich auf das Nächste vor</strong> – richte deinen Fokus auf das, was kommt.</li></ol><hr><p>| <em>Siehe auch: <a href="/en/education/mental-strength/pre-shot-routine">Leitfaden zur Vorbereitung auf die Impfung</a> | <a href="/en/education/mental-strength/handling-pressure">Umgang mit Druck</a> | <a href="/en/education/mindfulness/techniques">Achtsamkeitstechniken</a></em> |</p>',54)])])}]]);export{t as __pageData,a as default};
